// Host-half smoke test stub for @deepseek-ai/schemastery.
// The real package is only needed for schema *validation*; the host plugin
// only calls .default() on leaf schemas at definition time.
const chain = () => {
  const o = {}
  for (const m of ['default', 'min', 'max', 'required', 'description', 'role', 'step']) o[m] = () => o
  return o
}
export default {
  object: () => chain(),
  boolean: chain,
  string: chain,
  number: chain,
  natural: chain,
  percent: chain,
  union: () => chain(),
  array: () => chain(),
  const: chain,
  any: chain
}
